/**
 * A FINITE cycle certificate for the tree reduction — the provable form of "cycles contribute nothing".
 *
 * ## The problem this solves
 *
 * The central claim of the kinetic mapping is that cyclic fault propagation contributes negligibly, so a
 * global-graph RCA problem reduces to a tree. As `KINETIC_MAPPING_AUDIT.md` §1 records, the result it is taken
 * from is a **Boltzmann–Grad limit** statement, and its hypotheses — dilution, and molecular chaos (pre-collision
 * independence) — are not established for a 10–40 service graph whose load is generated by shared upstream
 * callers. So the claim has been an inherited asymptotics rather than a fact about the graph in front of us.
 *
 * ## What is proved here instead
 *
 * No limit is needed. In a directed graph with `n` nodes and maximum degree `d`, the number of closed walks of
 * length `L` is at most `n · d^L` — every walk extends by at most `d` choices per step — and **cycles are a
 * subset of closed walks**. If an anomaly loses a factor `α` per hop, the total contribution of all cycles of
 * length ≥ 3 is therefore at most
 *
 * ```
 *     Σ_{L≥3} C_L · α^L  ≤  n · Σ_{L≥3} (d·α)^L  =  n · (d·α)^3 / (1 − d·α)      whenever d·α < 1
 * ```
 *
 * That is a finite-size, checkable statement, and it plays the role the asymptotics was playing:
 *
 * - the **convergence condition `d·α < 1`** is the finite form of "the system is dilute enough for collisions to
 *   decay" — it is a property of THE GRAPH AND THE ATTENUATION, measurable per case, not a limit hypothesis;
 * - the **bound** is a number, so a case is either certified (bound < ε, the tree reduction is PROVED for it),
 *   refuted (d·α ≥ 1, the geometric series diverges and no such bound exists), or **uncertified** (convergent but
 *   above ε) — three answers where the asymptotics gave one assumption.
 *
 * The distinction matters because the assumption is right on average and the certificate is right per case:
 * knowing WHICH cases fail it is worth more than believing none of them do.
 *
 * @module optimize/cycle-bound
 */

/** A directed edge, in the only two fields this analysis reads. */
export interface DirectedEdge {
  readonly from: string;
  readonly to: string;
}

/** The two numbers a certificate is stated against. */
export interface CycleCertificateOptions {
  /** Per-hop attenuation of an anomaly, in (0, 1]. `1` means nothing is lost along an edge. */
  readonly alpha: number;
  /** The tolerance the cycle contribution must fall below. */
  readonly epsilon: number;
}

/** The verdict for one graph at one `(α, ε)`. */
export interface CycleCertificate {
  readonly nodes: number;
  readonly edges: number;
  /** Maximum IN-degree — how many callers a service can have, which is what bounds the walk count. */
  readonly maxInDegree: number;
  /** `d · α`. Below 1 the cycle sum converges; at or above it, it does not. */
  readonly geometricRatio: number;
  readonly bounded: boolean;
  /** `n · (dα)^3 / (1 − dα)`, or `Infinity` when the ratio does not converge. */
  readonly bound: number;
  /** `bound < ε`. The tree reduction is proved for this graph at this attenuation. */
  readonly certified: boolean;
}

/**
 * Certify the cycle reduction for one graph at one attenuation.
 *
 * @param edges - The graph's directed edges. Duplicates are ignored: the bound is on walks, and a repeated edge
 *        is the same choice.
 * @param nodeCount - The number of service nodes.
 * @param options - The attenuation and the tolerance.
 * @returns The verdict, including the ratio and the bound, so a caller can read WHY it failed rather than only
 *          that it did.
 */
export function cycleCertificate(
  edges: readonly DirectedEdge[],
  nodeCount: number,
  options: CycleCertificateOptions,
): CycleCertificate {
  const { alpha, epsilon } = options;
  // The in-degree of each target, over DISTINCT edges.
  const inDegree = new Map<string, number>();
  const seen = new Set<string>();
  for (const e of edges) {
    const key = `${e.from}>${e.to}`;
    if (seen.has(key)) continue;
    seen.add(key);
    inDegree.set(e.to, (inDegree.get(e.to) ?? 0) + 1);
  }
  // The bound uses the maximum in-degree, because a closed walk extends by choosing an INCOMING edge at each
  // step. `d = 0` means no edges at all, which is trivially certified.
  const maxInDegree = inDegree.size === 0 ? 0 : Math.max(...inDegree.values());
  const ratio = maxInDegree * alpha;
  if (maxInDegree === 0) {
    return {
      nodes: nodeCount,
      edges: seen.size,
      maxInDegree: 0,
      geometricRatio: 0,
      bounded: true,
      bound: 0,
      certified: true,
    };
  }
  // `>= 1` is the divergence boundary and is treated as unbounded, not as a large finite number: at `dα = 1` the
  // series 1 + 1 + 1 + … diverges, and rounding it into a finite bound would certify a graph the algebra does
  // not cover.
  const bounded = ratio < 1;
  const bound = bounded ? (nodeCount * ratio ** 3) / (1 - ratio) : Number.POSITIVE_INFINITY;
  return {
    nodes: nodeCount,
    edges: seen.size,
    maxInDegree,
    geometricRatio: ratio,
    bounded,
    bound,
    certified: bounded && bound < epsilon,
  };
}

/**
 * Render a certificate as the line a report carries.
 *
 * The three outcomes are named rather than collapsed into a boolean, because "no bound exists" and "the bound is
 * too large" are different findings about a case — the first refutes the reduction's use, the second only says
 * this attenuation is not enough to prove it.
 *
 * @param certificate - The verdict.
 * @param options - The `(α, ε)` it was computed at, so the line cannot be read without its parameters.
 * @returns One line, without a trailing newline.
 */
export function formatCycleCertificate(
  certificate: CycleCertificate,
  options: CycleCertificateOptions,
): string {
  const verdict = !certificate.bounded
    ? 'NOT BOUNDED (d*alpha >= 1)'
    : certificate.certified
      ? 'CERTIFIED'
      : 'UNCERTIFIED (convergent, above epsilon)';
  const bound = certificate.bounded ? certificate.bound.toExponential(3) : 'Infinity';
  return (
    `cycle certificate[alpha=${options.alpha}, eps=${options.epsilon.toExponential(0)}]: ` +
    `n=${certificate.nodes} edges=${certificate.edges} maxInDegree=${certificate.maxInDegree} ` +
    `d*alpha=${certificate.geometricRatio.toFixed(4)} bound=${bound} -> ${verdict}`
  );
}

/**
 * A per-hop transmission estimate, summarised.
 *
 * ## Why this exists
 *
 * The certificate above is a function of one parameter it does not itself determine: the per-hop attenuation
 * `α`. Until `α` is measured the certificate can only be swept, and a sweep answers "how strong would the
 * attenuation have to be?" rather than "is the reduction proved here?". This turns the sweep into a reading.
 *
 * The estimator is deliberately distribution-free: `median` is reported as the headline because a fault's
 * transmission has a long right tail (a victim can look worse than its source), and `p90` is reported beside it
 * because the certificate is a WORST-CASE bound — a reader needs to see how much of the distribution would fail
 * it, not only where its centre is.
 */
export interface AttenuationEstimate {
  readonly samples: number;
  readonly median: number;
  readonly mean: number;
  readonly p90: number;
  readonly min: number;
  readonly max: number;
}

/**
 * Summarise per-hop transmission samples.
 *
 * @param ratios - Each sample is `downstream / upstream` for one edge, in `[0, ∞)`. A ratio above 1 means the
 *        downstream service looked WORSE than its upstream, which a fault's own downstream victims routinely do.
 * @returns The summary, or `undefined` when there is nothing to summarise — an absent measurement is not a
 *          measurement of zero.
 */
export function measureAttenuation(ratios: readonly number[]): AttenuationEstimate | undefined {
  const finite = ratios.filter((r) => Number.isFinite(r) && r >= 0);
  if (finite.length === 0) return undefined;
  const sorted = [...finite].sort((a, b) => a - b);
  const at = (q: number): number =>
    // The `(n − 1)` basis, not `q · n`: with six samples the latter puts the "p90" at the maximum, so the tail
    // statistic would report the single worst edge rather than the shape of the tail — and a reader comparing it
    // with the median would be comparing two different conventions.
    sorted[Math.min(sorted.length - 1, Math.floor(q * (sorted.length - 1)))]!;
  return {
    samples: sorted.length,
    median: at(0.5),
    mean: sorted.reduce((a, b) => a + b, 0) / sorted.length,
    p90: at(0.9),
    min: sorted[0]!,
    max: sorted[sorted.length - 1]!,
  };
}

/**
 * Render an attenuation estimate as the line a report carries.
 *
 * @param estimate - The summary.
 * @param label - What the samples were (e.g. `anomaly-score ratio` vs `propagation weight`), because the two
 *        estimators are different quantities and a reader must not compare them as one.
 * @returns One line, without a trailing newline.
 */
export function formatAttenuation(estimate: AttenuationEstimate, label: string): string {
  return (
    `attenuation[${label}] n=${estimate.samples} median=${estimate.median.toFixed(4)} ` +
    `mean=${estimate.mean.toFixed(4)} p90=${estimate.p90.toFixed(4)} ` +
    `range=[${estimate.min.toFixed(4)}, ${estimate.max.toFixed(4)}]`
  );
}
